const rows = $input.all().map(r => r.json).filter(r => r.sku && r.product_name);
const today = new Date();
const alerts = [];
const criticalItems = [];
const watchItems = [];

for (const row of rows) {
  const currentStock = parseFloat(row.current_stock) || 0;
  const reorderPoint = parseFloat(row.reorder_point) || 0;
  const reorderQty = parseFloat(row.reorder_qty) || 0;
  const leadTimeDays = parseInt(row.lead_time_days) || 7;
  const avgDailySales = parseFloat(row.avg_daily_sales) || 0;
  const unitCost = parseFloat(row.unit_cost) || 0;
  const supplierName = row.supplier_name || '';
  const supplierEmail = row.supplier_email || '';
  const lastOrdered = row.last_ordered_date ? new Date(row.last_ordered_date) : null;
  const daysSinceOrder = lastOrdered ? Math.floor((today - lastOrdered) / 86400000) : 999;

  const daysOfStockLeft = avgDailySales > 0 ? Math.floor(currentStock / avgDailySales) : 999;
  const stockoutRisk = daysOfStockLeft <= leadTimeDays;
  const belowReorderPoint = currentStock <= reorderPoint;
  const reorderCost = reorderQty * unitCost;

  if (!belowReorderPoint && !stockoutRisk) continue;

  const urgency = currentStock === 0 ? 'out_of_stock' : stockoutRisk && daysOfStockLeft <= 2 ? 'critical' : belowReorderPoint ? 'reorder_now' : 'watch';

  const item = {
    sku: row.sku,
    productName: row.product_name,
    category: row.category || '',
    currentStock,
    reorderPoint,
    reorderQty,
    leadTimeDays,
    avgDailySales,
    daysOfStockLeft: daysOfStockLeft === 999 ? null : daysOfStockLeft,
    unitCost,
    reorderCost: parseFloat(reorderCost.toFixed(2)),
    supplierName,
    supplierEmail,
    daysSinceOrder,
    urgency,
    notes: row.notes || ''
  };

  alerts.push(item);
  if (urgency === 'out_of_stock' || urgency === 'critical') criticalItems.push(item);
  else watchItems.push(item);
}

alerts.sort((a, b) => {
  const order = {out_of_stock:0, critical:1, reorder_now:2, watch:3};
  return (order[a.urgency]||9) - (order[b.urgency]||9);
});

const totalReorderCost = alerts.filter(a => a.urgency !== 'watch').reduce((s,a) => s + a.reorderCost, 0);
const currency = rows[0]?.currency || 'USD';

return [{ json: { alerts, criticalItems, watchItems, totalAlerts: alerts.length, totalReorderCost: parseFloat(totalReorderCost.toFixed(2)), currency, scanDate: today.toISOString().split('T')[0], totalSkus: rows.length } }];

