const note = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const d = $('Check Reorder Levels').first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const urgencyConfig = {
  out_of_stock: {color:'#dc2626', bg:'#fef2f2', label:'OUT OF STOCK'},
  critical:     {color:'#ea580c', bg:'#fff7ed', label:'CRITICAL'},
  reorder_now:  {color:'#d97706', bg:'#fffbeb', label:'REORDER NOW'},
  watch:        {color:'#2563eb', bg:'#eff6ff', label:'WATCH'}
};
const cur = d.currency;
const rows = d.alerts.slice(0,25).map(item => {
  const uc = urgencyConfig[item.urgency]||urgencyConfig.watch;
  return `<tr style="border-bottom:1px solid #f3f4f6">
    <td style="padding:9px 12px"><div style="font-size:14px;font-weight:600">${esc(item.productName)}</div><div style="font-size:11px;color:#9ca3af">${esc(item.sku)}${item.category?' · '+esc(item.category):''}</div></td>
    <td style="padding:9px 12px;text-align:center"><span style="background:${uc.bg};color:${uc.color};font-size:10px;font-weight:700;padding:2px 7px;border-radius:8px">${uc.label}</span></td>
    <td style="padding:9px 12px;text-align:right;font-size:14px;font-weight:600;color:${item.currentStock===0?'#dc2626':'#111'}">${item.currentStock}</td>
    <td style="padding:9px 12px;text-align:right;font-size:13px;color:#6b7280">${item.reorderPoint}</td>
    <td style="padding:9px 12px;text-align:right;font-size:13px">${item.daysOfStockLeft!==null?item.daysOfStockLeft+'d':'—'}</td>
    <td style="padding:9px 12px;text-align:right;font-size:13px">${item.reorderQty}</td>
    <td style="padding:9px 12px;text-align:right;font-size:13px;font-weight:600">${cur}${item.reorderCost}</td>
    <td style="padding:9px 12px;font-size:12px;color:#6b7280">${esc(item.supplierName)}</td>
  </tr>`;
}).join('');
const noteHtml = note.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:800px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:4px">Inventory Alert · ${esc(d.scanDate)}</div>
    <div style="font-size:18px;font-weight:700">${d.totalAlerts} items need attention · ${cur}${d.totalReorderCost} reorder cost</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:3px">${d.criticalItems.length} critical · ${d.totalSkus} SKUs scanned</div>
  </div>
  <div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">Inventory analyst note</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0">${noteHtml}</p>
  </div>
  <div style="background:#fff;padding:0;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f9fafb;font-size:11px;text-transform:uppercase;color:#9ca3af">
        <th style="padding:8px 12px;text-align:left">Product</th>
        <th style="padding:8px 12px;text-align:center">Status</th>
        <th style="padding:8px 12px;text-align:right">Stock</th>
        <th style="padding:8px 12px;text-align:right">Reorder pt</th>
        <th style="padding:8px 12px;text-align:right">Days left</th>
        <th style="padding:8px 12px;text-align:right">Order qty</th>
        <th style="padding:8px 12px;text-align:right">Order cost</th>
        <th style="padding:8px 12px;text-align:left">Supplier</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>
  </div>
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:10px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Inventory Reorder Alert · ${esc(d.scanDate)}
  </div>
</div></body></html>`;
return [{ json: { html, totalAlerts: d.totalAlerts, criticalCount: d.criticalItems.length, totalReorderCost: d.totalReorderCost, currency: cur } }];

const body = $input.first().json.body;
if (!body.sku || body.current_stock === undefined) return [{ json: { valid: false, error: 'Missing sku or current_stock' } }];
return [{ json: { valid: true, sku: body.sku.trim(), currentStock: parseFloat(body.current_stock), notes: body.notes || '', updatedAt: new Date().toISOString() } }];
